package io.translab.tantor.server.service;

import com.fasterxml.jackson.databind.ObjectMapper;
import io.translab.tantor.server.config.AddNodeInspectionProperties;
import io.translab.tantor.server.domain.*;
import io.translab.tantor.server.repository.*;
import org.junit.jupiter.api.Test;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.util.ReflectionTestUtils;
import java.time.Instant;
import java.util.*;
import static io.translab.tantor.server.service.KafkaExpansionWorkflow.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

class KafkaExpansionLedgerTest {
    final KafkaExpansionOperationRepository ops=mock(KafkaExpansionOperationRepository.class);final ClusterRepository clusters=mock(ClusterRepository.class);final HostRepository hosts=mock(HostRepository.class);final ClusterServiceAssignmentRepository assignments=mock(ClusterServiceAssignmentRepository.class);final JobStepRepository steps=mock(JobStepRepository.class);final TaskRepository tasks=mock(TaskRepository.class);final JobService jobs=mock(JobService.class);final JdbcTemplate jdbc=mock(JdbcTemplate.class);final ObjectMapper mapper=new ObjectMapper().findAndRegisterModules();final AddNodeInspectionProperties policy=new AddNodeInspectionProperties();
    final KafkaExpansionLedger ledger=new KafkaExpansionLedger(ops,clusters,hosts,assignments,steps,tasks,jobs,jdbc,mapper,policy);
    KafkaExpansionOperation operation()throws Exception{var plan=new KafkaExpansionPlanTest().plan().freeze(mapper);var op=new KafkaExpansionOperation();op.setId(plan.plan().operationId());op.setClusterId(plan.plan().clusterId());op.setHostId(plan.plan().candidateHostId());op.setJobId(UUID.randomUUID());op.setPlan(plan.raw());op.setPlanDigest(plan.digest());op.setState(KafkaExpansionState.RECOVERY_REQUIRED);when(ops.findById(op.getId())).thenReturn(Optional.of(op));when(ops.findForUpdate(op.getId())).thenReturn(Optional.of(op));return op;}
    Step next(KafkaExpansionOperation op,Kind desired)throws Exception{var c=ledger.checkpoints(op);while(c.next().orElseThrow().kind()!=desired){var step=c.next().orElseThrow();c.intent(step.id());c.confirm(new Evidence(op.getPlanDigest(),step.id(),step.target(),Instant.now(),step.kind().requiredFacts()),Instant.now());}op.setCheckpoints(mapper.writeValueAsString(c.snapshot()));return c.next().orElseThrow();}
    JobStep jobStep(KafkaExpansionOperation op,Step workflow)throws Exception{var job=new Job();job.setId(op.getJobId());var step=new JobStep();step.setId(UUID.randomUUID());step.setJob(job);step.setPayload(mapper.writeValueAsString(workflow));when(steps.findById(step.getId())).thenReturn(Optional.of(step));return step;}
    @Test void releaseGatePreventsAnyReservationOrTaskCreation()throws Exception{assertThrows(org.springframework.web.server.ResponseStatusException.class,()->ledger.accept(new KafkaExpansionPlanTest().plan().freeze(mapper),"request-key-123456","a".repeat(64)));verifyNoInteractions(ops,clusters,jobs,tasks);}
    @Test void repeatedKeyReturnsTheOriginalRecoveryOperation()throws Exception{var op=operation();op.setRequestDigest("a".repeat(64));ReflectionTestUtils.setField(ledger,"executionEnabled",true);when(clusters.findForServiceUpdate(op.getClusterId())).thenReturn(Optional.of(new Cluster()));when(ops.findByClusterIdAndRequestKey(op.getClusterId(),"request-key-123456")).thenReturn(Optional.of(op));assertEquals(op.getJobId(),ledger.accept(ledger.frozen(op),"request-key-123456","a".repeat(64)).jobId());assertThrows(org.springframework.web.server.ResponseStatusException.class,()->ledger.accept(ledger.frozen(op),"request-key-123456","b".repeat(64)));verifyNoInteractions(tasks,hosts);}
    @Test void inFlightNativeTaskCannotBeReplacedOrChangedToInspection()throws Exception{var op=operation();var workflow=next(op,Kind.FORMAT);var step=jobStep(op,workflow);UUID taskId=UUID.randomUUID();when(jdbc.queryForList(anyString(),eq(op.getId()))).thenReturn(List.of(Map.of("task_id",taskId,"step_id",step.getId())));var pending=new Task();pending.setId(taskId);pending.setHostId(op.getHostId());pending.setCommand(KafkaExpansionLedger.CANDIDATE);pending.setParameters("{\"action\":\"FORMAT\"}");when(tasks.findById(taskId)).thenReturn(Optional.of(pending));assertSame(pending,ledger.dispatch(op.getId(),step.getId(),false,null));assertThrows(org.springframework.web.server.ResponseStatusException.class,()->ledger.dispatch(op.getId(),step.getId(),true,null));verify(tasks,never()).saveAndFlush(any());}
    @Test void uncertainMutationCannotReplayWithoutMatchingLinkedInspection()throws Exception{var op=operation();var workflow=next(op,Kind.FORMAT);var c=ledger.checkpoints(op);c.intent(workflow.id());op.setCheckpoints(mapper.writeValueAsString(c.snapshot()));var step=jobStep(op,workflow);assertThrows(org.springframework.web.server.ResponseStatusException.class,()->ledger.dispatch(op.getId(),step.getId(),false,null));assertEquals(State.INTENT,ledger.checkpoints(op).snapshot().get(workflow.id()));verify(tasks,never()).saveAndFlush(any());}
    @Test void nativeEffectCannotBeRecordedThroughServerOnlyIntent()throws Exception{var op=operation();var workflow=next(op,Kind.PREPARE);assertThrows(org.springframework.web.server.ResponseStatusException.class,()->ledger.beginServerStep(op.getId(),workflow.id()));verify(ops,never()).saveAndFlush(any());}
    @Test void cancellationNeedsDrainedTasksAndNoHistoricalMutation()throws Exception{var op=operation();when(clusters.findForServiceUpdate(op.getClusterId())).thenReturn(Optional.of(new Cluster()));when(jdbc.queryForObject(anyString(),eq(Integer.class),eq(op.getId()))).thenReturn(0,1);assertThrows(org.springframework.web.server.ResponseStatusException.class,()->ledger.cancelSafe(op.getClusterId(),op.getId()));assertTrue(op.getState().reserved());verify(ops,never()).saveAndFlush(any());}
    @Test void publicationCannotSkipStagesOrAcceptExpiredJointProof()throws Exception{var op=operation();var first=ledger.checkpoints(op).next().orElseThrow();assertThrows(org.springframework.web.server.ResponseStatusException.class,()->ledger.publish(op.getId(),new Evidence(op.getPlanDigest(),first.id(),first.target(),Instant.now(),Set.of("ALL_PLANNED_ROLES_VERIFIED"))));var publish=next(op,Kind.PUBLISH);assertThrows(org.springframework.web.server.ResponseStatusException.class,()->ledger.publish(op.getId(),new Evidence(op.getPlanDigest(),publish.id(),publish.target(),Instant.now().minusSeconds(61),Set.of("ALL_PLANNED_ROLES_VERIFIED"))));verifyNoInteractions(hosts,assignments);}
    @Test void excludedFrozenHostCannotReceiveAnyTask()throws Exception{var op=operation();var workflow=next(op,Kind.PREPARE);var step=jobStep(op,workflow);policy.setExcludedHostIds(List.of(op.getHostId()));assertThrows(org.springframework.web.server.ResponseStatusException.class,()->ledger.dispatch(op.getId(),step.getId(),false,null));verifyNoInteractions(tasks);}
    @Test void publicationStageCanRequestSeparateReadOnlyProofsForBothRoles()throws Exception{var op=operation();var workflow=next(op,Kind.PUBLISH);var step=jobStep(op,workflow);when(tasks.saveAndFlush(any())).thenAnswer(invocation->{Task t=invocation.getArgument(0);t.setId(UUID.randomUUID());return t;});var inspection=ledger.inspect(op.getId(),step.getId(),"candidate:controller");assertEquals(KafkaExpansionLedger.CANDIDATE,inspection.getCommand());assertEquals("INSPECT",mapper.readTree(inspection.getParameters()).path("action").asText());assertEquals(State.PENDING,ledger.checkpoints(op).snapshot().get(workflow.id()));}
}
